import {mountBannerImage} from './banner-image.js';
import {sortedBanners} from './banner-data.js';
export function mountAdminBanners(root,client,isCurrent=()=>true){
 root.classList.add('banner-manager');root.innerHTML='<h3>แบนเนอร์ประชาสัมพันธ์หน้าแรก</h3><p class="sub">ใช้ประชาสัมพันธ์ข่าวหรืองานอื่นได้โดยไม่ต้องสร้างกิจกรรมรับสมัคร · แสดงได้สูงสุด 20 รายการ · รูปแนวนอนแนะนำ 1800 × 650 px และรูปมือถือ 960 × 540 px (ไม่บังคับ)</p><button class="primary" data-add>+ เพิ่มแบนเนอร์</button><div data-editor></div><p role="status" data-status></p><div class="banner-list"></div>';
 const list=root.querySelector('.banner-list'),editor=root.querySelector('[data-editor]'),status=root.querySelector('[data-status]'),add=root.querySelector('[data-add]');let items=[],disposed=false,stopEditor=()=>{},editingId=null,editingVersion=null,editorVersion=0;
 const active=()=>!disposed&&isCurrent();
 function closeEditor(){stopEditor();stopEditor=()=>{};editorVersion++;editingId=null;editingVersion=null;editor.replaceChildren();add.disabled=false}
 function edit(item=null){if(!active())return;closeEditor();const version=++editorVersion,id=item?.id||crypto.randomUUID();editingId=id;editingVersion=item?.version??null;add.disabled=true;
  const form=document.createElement('form');form.className='panel';form.innerHTML='<h4></h4><div class="banner-editor"><label class="full">ชื่อเรื่อง / คำอธิบายภาพ<input name="title" maxlength="160" required></label><label class="full">ลิงก์เมื่อกดภาพ (ไม่บังคับ)<input name="linkUrl" placeholder="https://... หรือ #live-events" maxlength="1000"></label><label>ลำดับการแสดง (เลขน้อยขึ้นก่อน)<input name="sortOrder" type="number" min="0" max="9999" step="1" required></label><label><input name="published" type="checkbox"> แสดงบนหน้าแรก</label><div class="full" data-desktop></div><div class="full" data-mobile></div></div><p class="sub">ระบบย่อรูปให้โดยไม่ตัดภาพ รูปที่เปลี่ยนจะใช้หลังจากกดบันทึก</p><p class="banner-stale" role="status"></p><div class="banner-save-actions"><button type="submit" class="primary">บันทึกแบนเนอร์</button><button type="button" data-cancel>ยกเลิก</button></div><p data-result role="status"></p>';editor.append(form);form.querySelector('h4').textContent=item?'แก้ไขแบนเนอร์':'เพิ่มแบนเนอร์';form.elements.title.value=item?.title||'';form.elements.linkUrl.value=item?.linkUrl||'';form.elements.sortOrder.value=item?.sortOrder??items.length+1;form.elements.published.checked=item?.published??true;
  for(const [key,container] of [['imageUrl','[data-desktop]'],['mobileImageUrl','[data-mobile]']])if(item?.[key]){const img=document.createElement('img');img.src=item[key];img.alt='ภาพปัจจุบัน';img.className='banner-preview';form.querySelector(container).append(img)}
  const desktop=mountBannerImage(form.querySelector('[data-desktop]'),item?'เปลี่ยนภาพคอมพิวเตอร์ (ไม่เลือก = ใช้ภาพเดิม)':'ภาพแบนเนอร์หลัก'),mobile=mountBannerImage(form.querySelector('[data-mobile]'),'ภาพสำหรับมือถือ (ไม่บังคับ)');
  if(item?.mobileImageUrl){const label=document.createElement('label');label.innerHTML='<input type="checkbox" name="removeMobile"> ใช้ภาพหลักบนมือถือแทนภาพมือถือเดิม';form.querySelector('[data-mobile]').append(label)}
  stopEditor=()=>{desktop.dispose();mobile.dispose()};form.querySelector('[data-cancel]').onclick=closeEditor;
  let uploadedDesktop=null,uploadedMobile=null,desktopInput=null,mobileInput=null,busy=false;
  form.onsubmit=async event=>{event.preventDefault();if(busy||!active())return;busy=true;form.querySelectorAll('button,input').forEach(el=>el.disabled=true);const message=form.querySelector('[data-result]');message.textContent='กำลังบันทึก…';
   try{const desktopBlob=await desktop.value(),mobileBlob=await mobile.value();if(!active()||version!==editorVersion)return;
    if(desktopBlob&&desktopInput!==desktopBlob){uploadedDesktop=await client.uploadBannerImage(id,desktopBlob);desktopInput=desktopBlob}if(!active()||version!==editorVersion)return;
    if(mobileBlob&&mobileInput!==mobileBlob){uploadedMobile=await client.uploadBannerImage(id,mobileBlob);mobileInput=mobileBlob}if(!active()||version!==editorVersion)return;
    const imageUrl=desktopBlob?uploadedDesktop:item?.imageUrl;if(!imageUrl)throw new Error('กรุณาเลือกภาพแบนเนอร์หลัก');
    await client.operate({action:'saveBanner',bannerId:id,expectedVersion:item?.version||0,banner:{title:form.elements.title.value.trim(),linkUrl:form.elements.linkUrl.value.trim(),sortOrder:Number(form.elements.sortOrder.value),published:form.elements.published.checked,imageUrl,mobileImageUrl:form.elements.removeMobile?.checked?'':mobileBlob?uploadedMobile:item?.mobileImageUrl||''}});
    if(active()&&version===editorVersion){closeEditor();status.textContent='บันทึกแบนเนอร์แล้ว หน้าแรกอัปเดตอัตโนมัติ'}
   }catch(error){if(active()&&version===editorVersion)message.textContent=error.message||'บันทึกไม่ได้ กรุณาลองใหม่'}finally{busy=false;if(active()&&version===editorVersion)form.querySelectorAll('button,input').forEach(el=>el.disabled=false)}
  };
  form.elements.title.focus();
 }
 function paint(){list.replaceChildren();if(!items.length){list.textContent='ยังไม่มีแบนเนอร์ กดเพิ่มแบนเนอร์เพื่อเริ่มประชาสัมพันธ์';return}for(const item of items){const row=document.createElement('article');row.className='banner-row';const image=document.createElement('img');image.src=item.imageUrl;image.alt=item.title;image.loading='lazy';const content=document.createElement('div');content.className='banner-row-content';const heading=document.createElement('h4');heading.textContent=item.title;const info=document.createElement('p');info.className='sub';info.textContent='ลำดับ '+item.sortOrder+' · '+(item.published?'แสดงบนหน้าแรก':'ซ่อนไว้');content.append(heading,info);const actions=document.createElement('div');actions.className='banner-row-actions';
   const make=(text,handler)=>{const b=document.createElement('button');b.type='button';b.textContent=text;b.onclick=async()=>{if(!active())return;b.disabled=true;try{await handler()}catch(error){if(active())status.textContent=error.message||'ทำรายการไม่ได้'}finally{if(active())b.disabled=false}};actions.append(b)};
   make('แก้ไข',()=>edit(item));make(item.published?'ซ่อน':'แสดง',async()=>{await client.operate({action:'saveBanner',bannerId:item.id,expectedVersion:item.version,banner:{...item,published:!item.published}});if(active())status.textContent='เปลี่ยนสถานะแบนเนอร์แล้ว'});
   make('ลบ',async()=>{if(!confirm('ลบแบนเนอร์ “'+item.title+'” ออกจากหน้าเว็บ?'))return;await client.operate({action:'deleteBanner',bannerId:item.id,expectedVersion:item.version});if(active()){if(editingId===item.id)closeEditor();status.textContent='ลบแบนเนอร์ออกจากหน้าเว็บแล้ว'}});
   content.append(actions);row.append(image,content);list.append(row)}
 }
 add.onclick=()=>edit();const unsubscribe=client.watchBanners(data=>{if(!active())return;items=sortedBanners(data);paint();if(editingId&&editingVersion!==null){const current=items.find(item=>item.id===editingId),stale=editor.querySelector('.banner-stale');if(stale)stale.textContent=current?.version===editingVersion?'':'ข้อมูลเปลี่ยนหรือลบแล้ว กรุณายกเลิกและเปิดรายการล่าสุดก่อนบันทึก'}},()=>{if(active()){items=[];list.replaceChildren();status.textContent='โหลดแบนเนอร์ไม่ได้ กรุณาตรวจสิทธิ์หรือเข้าสู่ระบบใหม่'}},{admin:true});
 return ()=>{disposed=true;unsubscribe();stopEditor()};
}
